from itertools import product

def atoms(outcomes, X):
    """Group outcomes by the value of X. Groups come ordered by that value."""
    groups = {}
    for w in outcomes:
        groups.setdefault(X(w), []).append(w)
    return [groups[v] for v in sorted(groups)]

def n_events(atoms):
    """The number of events: every union of atoms."""
    return 2 ** len(atoms)

def is_measurable(Y, atoms):
    """True when Y takes a single value on every atom."""
    return all(len({Y(w) for w in a}) == 1 for a in atoms)
